void QThreadData::clearEvents()
{
    // The destructor of an event may post new events (e.g. by calling
    // deleteLater()), which locks the mutex and modifies the list. So take
    // the events out of the list while holding the mutex, delete them after
    // unlocking it, and repeat until no new events have been posted.
    while (true) {
        QList<QPostEvent> events;
        {
            const auto locker = qt_scoped_lock(postEventList.mutex);
            if (postEventList.isEmpty())
                break;
            events.swap(postEventList);
            postEventList.startOffset = 0;
            postEventList.insertionOffset = 0;
            for (const QPostEvent &pe : std::as_const(events)) {
                if (pe.event) {
                    pe.receiver->d_func()->postedEvents.fetchAndSubAcquire(1);
                    pe.event->m_posted = false;
                }
            }
        }
        for (const QPostEvent &pe : std::as_const(events))
            delete pe.event;
    }
}

